package com.example.bandlink.controller; import com.example.bandlink.repository.UserRepository; import com.example.bandlink.service.PostImageService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/posts/{postId}/images") public class PostImageController{private final PostImageService service;private final UserRepository users;public PostImageController(PostImageService s,UserRepository u){service=s;users=u;}@PostMapping public ResponseEntity<String> add(Authentication a,@PathVariable Long postId,@RequestParam MultipartFile file){Long uid=users.findByEmail(a.getName()).orElseThrow().getId();return ResponseEntity.status(HttpStatus.CREATED).body(service.add(uid,postId,file));}}
